<script setup>
import { computed, nextTick, ref, watch } from 'vue'
import { useRouter, useRoute } from 'vue-router'
import { createResource, toast } from 'frappe-ui'

const props = defineProps({ name: { type: String, required: true } })

const router = useRouter()
const route = useRoute()
function goBack() {
	router.push({ name: 'ToDoList' })
}
function goEdit() {
	router.push({ name: 'EditToDo', params: { name: props.name } })
}

const TABS = [
	{ key: 'details', label: 'ToDo Details' },
	{ key: 'messages', label: 'Messages' },
]
const tab = ref(route.query.tab === 'messages' ? 'messages' : 'details')

const STATUS_OPTIONS = ['Open', 'Closed', 'Cancelled']

// ===== Detail =====
const detailRes = createResource({
	url: 'juragan.api.portal.todo.get_todo',
	method: 'GET',
	auto: true,
	makeParams: () => ({ name: props.name }),
})
const detail = computed(() => detailRes.data)

// Reference Type → nama route detail dokumennya. Deviasi belum punya halaman
// detail di portal, jadi tidak bisa dibuka (tombol disabled).
const REFERENCE_ROUTE = {
	'Data Pengajuan': 'DataPengajuanDetail',
}
const canOpenReference = computed(
	() =>
		!!detail.value &&
		!!REFERENCE_ROUTE[detail.value.reference_type] &&
		!!detail.value.reference_name
)
function openReference() {
	if (!canOpenReference.value) return
	router.push({
		name: REFERENCE_ROUTE[detail.value.reference_type],
		params: { name: detail.value.reference_name },
	})
}

// ===== Messages =====
const msgScroll = ref(null)
const messagesRes = createResource({
	url: 'juragan.api.portal.todo.get_todo_messages',
	method: 'GET',
	makeParams: () => ({ name: props.name }),
})
const messages = computed(() => messagesRes.data || [])

let messagesLoaded = false
function loadMessages() {
	if (messagesLoaded) return
	messagesLoaded = true
	messagesRes.fetch().then(scrollToBottom)
}
watch(tab, (t) => {
	if (t === 'messages') loadMessages()
})
if (tab.value === 'messages') loadMessages()

function scrollToBottom() {
	nextTick(() => {
		const el = msgScroll.value
		if (el) el.scrollTop = el.scrollHeight
	})
}

const draft = ref('')
const sending = ref(false)
const addMsgRes = createResource({
	url: 'juragan.api.portal.todo.add_todo_message',
	method: 'POST',
})
async function sendMessage() {
	const content = draft.value.trim()
	if (!content || sending.value) return
	sending.value = true
	try {
		const msg = await addMsgRes.submit({ name: props.name, content })
		messagesRes.setData([...(messagesRes.data || []), msg])
		draft.value = ''
		scrollToBottom()
	} catch (e) {
		toast.error(e?.messages?.[0] || e?.message || 'Gagal mengirim pesan.')
	} finally {
		sending.value = false
	}
}

// ===== Update Status =====
const showStatusUpdate = ref(false)
const updatingStatus = ref(false)
const updateStatusRes = createResource({
	url: 'juragan.api.portal.todo.update_todo_status',
	method: 'POST',
})
async function updateStatus(status) {
	if (updatingStatus.value) return
	if (detail.value && detail.value.status === status) {
		showStatusUpdate.value = false
		return
	}
	updatingStatus.value = true
	try {
		await updateStatusRes.submit({ name: props.name, status })
		if (detailRes.data) detailRes.setData({ ...detailRes.data, status })
		toast.success(`Status diubah ke ${status}.`)
		showStatusUpdate.value = false
	} catch (e) {
		toast.error(e?.messages?.[0] || e?.message || 'Gagal mengubah status.')
	} finally {
		updatingStatus.value = false
	}
}

// ===== Delete =====
const showDelete = ref(false)
const deleting = ref(false)
const deleteRes = createResource({
	url: 'juragan.api.portal.todo.delete_todo',
	method: 'POST',
})
async function removeTodo() {
	if (deleting.value) return
	deleting.value = true
	try {
		await deleteRes.submit({ name: props.name })
		toast.success('ToDo dihapus.')
		router.push({ name: 'ToDoList' })
	} catch (e) {
		toast.error(e?.messages?.[0] || e?.message || 'Gagal menghapus ToDo.')
	} finally {
		deleting.value = false
	}
}

// ===== Tampilan =====
function plainText(html) {
	if (!html) return ''
	return String(html)
		.replace(/<[^>]*>/g, ' ')
		.replace(/&nbsp;/g, ' ')
		.replace(/\s+/g, ' ')
		.trim()
}

const PRIORITY_PILL = {
	High: 'border-ui-line-red-200 text-ui-ink-red-500',
	Medium: 'border-ui-line-amber-200 text-ui-ink-amber-500',
	Low: 'border-ui-line-blue-200 text-ui-ink-blue-500',
}
const PRIORITY_DOT = {
	High: 'bg-red-500',
	Medium: 'bg-ui-surface-amber-400',
	Low: 'bg-blue-500',
}
function priorityPillClass(p) {
	return PRIORITY_PILL[p] || PRIORITY_PILL.Low
}
function priorityDotClass(p) {
	return PRIORITY_DOT[p] || PRIORITY_DOT.Low
}

function initials(name) {
	const parts = String(name || '')
		.trim()
		.split(/\s+/)
		.filter(Boolean)
	if (!parts.length) return '?'
	if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase()
	return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase()
}

const MONTHS_ABBR = [
	'Jan',
	'Feb',
	'Mar',
	'Apr',
	'May',
	'Jun',
	'Jul',
	'Aug',
	'Sep',
	'Oct',
	'Nov',
	'Dec',
]
function formatDate(v) {
	if (!v) return '—'
	const [y, m, d] = String(v).split('-').map(Number)
	if (!y || !m || !d) return String(v)
	return `${d} ${MONTHS_ABBR[m - 1]} ${y}`
}
function formatTime(v) {
	if (!v) return ''
	const d = new Date(String(v).replace(' ', 'T'))
	if (isNaN(d)) return ''
	const hh = String(d.getHours()).padStart(2, '0')
	const mm = String(d.getMinutes()).padStart(2, '0')
	return `${d.getDate()} ${MONTHS_ABBR[d.getMonth()]} ${d.getFullYear()}, ${hh}:${mm}`
}
</script>
